package com.coffeeshop.service;import com.coffeeshop.model.DocumentModels;import com.coffeeshop.repository.DocumentRepository;import java.util.*;public final class DocumentService{private static final Set<String>TYPES=Set.of("RECEIPT","INVOICE");private final DocumentRepository repository;public DocumentService(DocumentRepository r){repository=Objects.requireNonNull(r);}public DocumentModels.Catalog catalog(){return repository.load();}public long issue(long orderId,String type,long user){if(orderId<=0)throw new IllegalArgumentException("Select a completed order.");if(user<=0)throw new IllegalArgumentException("An authenticated user is required.");String t=type==null?"":type.toUpperCase(Locale.ROOT);if(!TYPES.contains(t))throw new IllegalArgumentException("Select receipt or invoice.");return repository.issue(orderId,t,user);}}
